<?php
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/admin-layout.php';
register_shutdown_function('admin_portal_footer');
require_role(['admin','super_admin']); $user=current_user(); $agentId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$agentId){http_response_code(404);exit('Agent not found.');} $errors=[];
$load=function()use($pdo,$agentId){$stmt=$pdo->prepare('SELECT a.*,u.first_name,u.last_name,u.email,u.phone,u.country FROM agents a JOIN users u ON u.id=a.user_id WHERE a.id=? LIMIT 1');$stmt->execute([$agentId]);return $stmt->fetch();}; $agent=$load(); if(!$agent){http_response_code(404);exit('Agent not found.');}
$accepted=['approved','admission_issued','visa_processing','enrolled'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf($_POST['_csrf']??''))$errors[]='Your session expired. Refresh and try again.'; $action=$_POST['action']??''; $applicationId=filter_input(INPUT_POST,'application_id',FILTER_VALIDATE_INT);
 if(!$errors&&$action==='status'){ $status=$_POST['approval_status']??''; if(!in_array($status,['pending','approved','rejected','suspended'],true))$errors[]='Choose a valid status.'; else{$now=date('Y-m-d H:i:s');$pdo->prepare('UPDATE agents SET approval_status=?,approved_by=?,approved_at=?,updated_at=? WHERE id=?')->execute([$status,$status==='approved'?$user['id']:null,$status==='approved'?$now:null,$now,$agentId]);$agent=$load();} }
 if(!$errors&&$action==='fee_paid'){ $fee=(float)($_POST['initial_fee_amount']??0);$check=$pdo->prepare("SELECT a.id,a.status FROM applications a JOIN students s ON s.id=a.student_id WHERE a.id=? AND (s.agent_id=? OR a.agent_id=?) LIMIT 1");$check->execute([$applicationId,$agentId,$agentId]);$application=$check->fetch();if(!$application||!in_array($application['status'],$accepted,true))$errors[]='The student must be accepted before commission eligibility can be created.';elseif($fee<0)$errors[]='Enter a valid initial fee amount.';else{try{$pdo->beginTransaction();$now=date('Y-m-d H:i:s');$pdo->prepare('UPDATE applications SET initial_fee_paid=1,initial_fee_paid_at=?,updated_at=? WHERE id=?')->execute([$now,$now,$applicationId]);$pdo->prepare("INSERT INTO agent_commissions (agent_id,application_id,amount,status) SELECT ?,?,?, 'pending' FROM dual WHERE NOT EXISTS (SELECT 1 FROM agent_commissions WHERE application_id=?)")->execute([$agentId,$applicationId,round($fee*((float)$agent['commission_rate']/100),2),$applicationId]);$pdo->commit();}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();$errors[]='The initial fee could not be recorded.';}} }
 if(!$errors&&$action==='receive'){ $commissionId=filter_input(INPUT_POST,'commission_id',FILTER_VALIDATE_INT);$stmt=$pdo->prepare("SELECT id FROM agent_commissions WHERE id=? AND agent_id=? AND status='pending' LIMIT 1");$stmt->execute([$commissionId,$agentId]);if(!$stmt->fetch())$errors[]='Commission record not found.';else{$now=date('Y-m-d H:i:s');$pdo->prepare("UPDATE agent_commissions SET status='received',received_at=?,received_by=?,updated_at=? WHERE id=?")->execute([$now,$user['id'],$now,$commissionId]);}}
}
$studentStmt=$pdo->prepare("SELECT s.id,u.first_name,u.last_name,u.email,a.id application_id,a.status,a.initial_fee_paid FROM students s JOIN users u ON u.id=s.user_id LEFT JOIN applications a ON a.id=(SELECT MAX(a2.id) FROM applications a2 WHERE a2.student_id=s.id) WHERE s.agent_id=? ORDER BY s.created_at DESC");$studentStmt->execute([$agentId]);$students=$studentStmt->fetchAll();
$commissionStmt=$pdo->prepare("SELECT c.*,u.first_name,u.last_name FROM agent_commissions c JOIN applications a ON a.id=c.application_id JOIN students s ON s.id=a.student_id JOIN users u ON u.id=s.user_id WHERE c.agent_id=? ORDER BY c.created_at DESC");$commissionStmt->execute([$agentId]);$commissions=$commissionStmt->fetchAll();$pending=array_filter($commissions,fn($item)=>$item['status']==='pending');$received=array_filter($commissions,fn($item)=>$item['status']==='received');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agent details | Medcon Admin</title><link rel="stylesheet" href="<?= esc(app_url('assets/css/app.css')) ?>"></head><body class="medcon-app mc-role-body"><header class="mc-role-topbar"><a href="<?= esc(app_url('admin/dashboard.php')) ?>" class="mc-portal-logo"><img src="<?= esc(site_url('img/logo.svg')) ?>" alt="Medcon"><span>Admin portal</span></a><nav class="mc-admin-nav"><a href="<?= esc(app_url('admin/dashboard.php')) ?>">Applications</a><a href="<?= esc(app_url('admin/agents.php')) ?>" aria-current="page">Agents</a><a href="<?= esc(app_url('admin/leads.php')) ?>">Eligibility leads</a></nav><div class="mc-portal-user"><span><?= esc($user['full_name']) ?></span><a href="<?= esc(app_url('logout.php')) ?>">Sign out</a></div></header><main class="mc-role-main"><div class="mc-portal-heading"><div><span class="mc-kicker">Agent <?= esc($agent['referral_code']) ?></span><h1><?= esc($agent['first_name'].' '.$agent['last_name']) ?></h1><p><?= esc($agent['email']) ?> · <?= esc($agent['organization_name']?:'No organization') ?></p></div><a class="mc-arrow-link" href="<?= esc(app_url('admin/agents.php')) ?>">Back to agents</a></div><?php if($errors): ?><div class="mc-errors" role="alert"><?php foreach($errors as $error): ?><div><?= esc($error) ?></div><?php endforeach; ?></div><?php endif; ?><section class="mc-panel"><div class="mc-section-head"><div><h2>Agent status</h2><p>Only approved agents can access the portal and receive referrals.</p></div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="status"><select name="approval_status"><option value="pending"<?= $agent['approval_status']==='pending'?' selected':'' ?>>Pending</option><option value="approved"<?= $agent['approval_status']==='approved'?' selected':'' ?>>Approved</option><option value="rejected"<?= $agent['approval_status']==='rejected'?' selected':'' ?>>Rejected</option><option value="suspended"<?= $agent['approval_status']==='suspended'?' selected':'' ?>>Suspended</option></select><button class="mc-btn-secondary" type="submit">Save status</button></form></div><dl class="mc-detail-list"><div><dt>Referral link</dt><dd><?= esc(site_url('a/'.$agent['referral_slug'])) ?></dd></div><div><dt>Commission rate</dt><dd><?= esc($agent['commission_rate']) ?>%</dd></div><div><dt>Experience</dt><dd><?= nl2br(esc($agent['recruitment_experience']?:'Not supplied')) ?></dd></div></dl></section><section class="mc-panel"><h2>Students (<?= count($students) ?>)</h2><?php if($students): ?><div class="mc-table-wrap"><table><thead><tr><th>Student</th><th>Application</th><th>Initial fee</th><th>Eligibility</th></tr></thead><tbody><?php foreach($students as $student): $acceptedStudent=in_array($student['status'],$accepted,true); ?><tr><td><strong><?= esc($student['first_name'].' '.$student['last_name']) ?></strong><br><small><?= esc($student['email']) ?></small></td><td><?= esc(application_status_label($student['status'])) ?></td><td><?= $student['initial_fee_paid']?'Paid':'Not paid' ?></td><td><?php if($acceptedStudent&&!$student['initial_fee_paid']): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="fee_paid"><input type="hidden" name="application_id" value="<?= (int)$student['application_id'] ?>"><input name="initial_fee_amount" type="number" min="0" step="0.01" placeholder="Initial fee" required><button class="mc-btn-secondary" type="submit">Record fee</button></form><?php elseif($acceptedStudent): ?>Commission eligible / recorded<?php else: ?>Eligible after acceptance + fee paid<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p>No referred students yet.</p><?php endif; ?></section><section class="mc-panel"><h2>Pending commissions (<?= count($pending) ?>)</h2><?php if($pending): ?><div class="mc-table-wrap"><table><thead><tr><th>Student</th><th>Amount</th><th>Action</th></tr></thead><tbody><?php foreach($pending as $commission): ?><tr><td><?= esc($commission['first_name'].' '.$commission['last_name']) ?></td><td><?= esc(number_format((float)$commission['amount'],2)) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="receive"><input type="hidden" name="commission_id" value="<?= (int)$commission['id'] ?>"><button class="mc-btn-secondary" type="submit">Mark received</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p>No pending commissions.</p><?php endif; ?></section><section class="mc-panel"><h2>Commissions received (<?= count($received) ?>)</h2><?php if($received): ?><div class="mc-table-wrap"><table><thead><tr><th>Student</th><th>Amount</th><th>Received</th></tr></thead><tbody><?php foreach($received as $commission): ?><tr><td><?= esc($commission['first_name'].' '.$commission['last_name']) ?></td><td><?= esc(number_format((float)$commission['amount'],2)) ?></td><td><?= esc(date('j M Y',strtotime($commission['received_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p>No commissions received.</p><?php endif; ?></section></main></body></html>
